28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "membership_number")
60	    private Integer membershipNumber;
61	
62	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
63	    private Set<Pet> pets;
64	
65	    public String getAddress() {
66	        return this.address;
67	    }
68	
69	    public void setAddress(String address) {
70	        this.address = address;
71	    }
72	
73	    public String getCity() {
74	        return this.city;
75	    }
76	
77	    public void setCity(String city) {
78	        this.city = city;
79	    }
80	
81	    public String getTelephone() {
82	        return this.telephone;
83	    }
84	
85	    public void setTelephone(String telephone) {
86	        this.telephone = telephone;
87	    }
88	
89	    public String getEmail() {
90	        return this.email;
91	    }
92	
93	    public void setEmail(String email) {
94	        this.email = email;
95	    }
96	
97	    public LocalDate getRegistrationDate() {
98	        return this.registrationDate;
99	    }
100	
101	    public void setRegistrationDate(LocalDate registrationDate) {
102	        this.registrationDate = registrationDate;
103	    }
104	
105	    public Integer getMembershipNumber() {
106	        return this.membershipNumber;
107	    }
108	
109	    public void setMembershipNumber(Integer membershipNumber) {
110	        this.membershipNumber = membershipNumber;
111	    }
112	
113	    /**
114	     * The owner's display name, formatted as 'LastName, FirstName'.
115	     */
116	    @Transient
117	    public String getDisplayName() {
118	        return this.getLastName() + ", " + this.getFirstName();
119	    }
120	
121	    /**
122	     * The owner's initials: the upper-cased first letters of the first and last
123	     * name, dot-separated with a trailing dot, e.g. 'J.S.'.
124	     */
125	    @Transient
126	    public String getInitials() {
127	        return (this.getFirstName().substring(0, 1) + "." + this.getLastName().substring(0, 1) + ".")
128	            .toUpperCase();
129	    }
130	
131	    protected Set<Pet> getPetsInternal() {
132	        if (this.pets == null) {
133	            this.pets = new HashSet<>();
134	        }
135	        return this.pets;
