17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        this.clinicService.saveOwner(owner);
105	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
106	        headers.setLocation(UriComponentsBuilder.newInstance()
107	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
108	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
114	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
115	        if (currentOwner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        currentOwner.setAddress(ownerFieldsDto.getAddress());
119	        currentOwner.setCity(ownerFieldsDto.getCity());
120	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
121	        currentOwner.setLastName(ownerFieldsDto.getLastName());
122	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
123	        currentOwner.setEmail(ownerFieldsDto.getEmail());
124	        this.clinicService.saveOwner(currentOwner);
125	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
126	    }
127	
128	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
129	    @Transactional
130	    @Override
131	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
132	        Owner owner = this.clinicService.findOwnerById(ownerId);
133	        if (owner == null) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        this.clinicService.deleteOwner(owner);
137	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        HttpHeaders headers = new HttpHeaders();
148	        Pet pet = petMapper.toPet(petFieldsDto);
149	        owner.setId(ownerId);
150	        pet.setOwner(owner);
151	        pet.getType().setName(null);
152	        this.clinicService.savePet(pet);
153	        PetDto petDto = petMapper.toPetDto(pet);
154	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
155	            .buildAndExpand(pet.getId()).toUri());
156	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
162	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
163	        if (currentOwner != null) {
164	            Pet currentPet = this.clinicService.findPetById(petId);
165	            if (currentPet != null) {
166	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
167	                currentPet.setName(petFieldsDto.getName());
168	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
169	                this.clinicService.savePet(currentPet);
170	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
171	            }
172	        }
173	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
179	        HttpHeaders headers = new HttpHeaders();
180	        Visit visit = visitMapper.toVisit(visitFieldsDto);
181	        Pet pet = new Pet();
182	        pet.setId(petId);
183	        visit.setPet(pet);
184	        this.clinicService.saveVisit(visit);
185	        VisitDto visitDto = visitMapper.toVisitDto(visit);
186	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
187	            .buildAndExpand(visit.getId()).toUri());
188	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
189	    }
190	
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
195	        Owner owner = this.clinicService.findOwnerById(ownerId);
196	        if (owner != null) {
197	            Pet pet = owner.getPet(petId);
198	            if (pet != null) {
199	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
200	            }
201	        }
202	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	    }
204	}
